const key='staseravolley-v005-design-demo-v1';
let state;try{state=JSON.parse(localStorage.getItem(key))||{}}catch{state={}}
let page='serate',selected=0,choosing=false,slot=null,day='all',query='';
const names=['Elena','Davide','Matteo','Simone','Alessia','Chiara','Lorenzo','Martina','Andrea','Marco','Giulia'];
const events=[{name:'Brescia Volley Friends',city:'Brescia',venue:'Palestra Demo Friends',hour:'20:30',price:7,logo:'bs-friends',members:16},{name:'Leonessa Volley Club',city:'Brescia',venue:'Palestra Demo Leonessa',hour:'21:00',price:8,logo:'bs-leonessa',members:18},{name:'Smash & Fun',city:'Bergamo',venue:'Palestra demo del gruppo',hour:'21:00',price:6,logo:'smash',members:20}];
const $=s=>document.querySelector(s),h=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=i=>`assets/avatars/bg-${String(i+1).padStart(2,'0')}.jpg`;
const date=i=>{let d=new Date();d.setDate(d.getDate()+i+1);return d.toLocaleDateString('it-IT',{weekday:'short',day:'numeric',month:'short'})};
const save=()=>localStorage.setItem(key,JSON.stringify(state));
const status=i=>state['booking'+i]||'none';
const logo=i=>`<span class="logo" style="display:grid;place-items:center;background:${['#d8e7dc','#ebe1d1','#d9e6f0'][i]};font-size:23px">${['✺','✷','✳'][i]}</span>`;
const card=i=>{let e=events[i];return `<button class="event" data-event="${i}">${logo(i)}<div><h3>${e.name}</h3><small>${date(i)} · ${e.hour}<br>${e.venue} · ${e.city}</small></div><div class="right"><strong>€${e.price}</strong><p class="available">${status(i)==='confirmed'||status(i)==='paid'?'Prenotato':'1 posto libero'}</p></div></button>`};
const head=(title,sub='')=>`<div class="intro"><span class="eyebrow">StaseraVolley · proposta demo</span><h1>${title}</h1><p class="muted">${sub}</p></div>`;
const back=()=>'<button class="back" data-go="serate" aria-label="Torna alle serate">←</button>';
function render(){let e=events[selected],b=status(selected);$('#dot').hidden=!events.some((_,i)=>status(i)==='confirmed');$('nav').innerHTML=[['home','⌂','Home'],['serate','◉','Serate'],['groups','♧','Gruppi'],['profile','☺','Profilo']].map(([id,ic,label])=>`<button data-go="${id}" class="${page===id?'active':''}"><span>${ic}</span>${label}</button>`).join('');
let content='';
if(page==='serate')content=head('Si gioca vicino a te.','Scegli una serata. Il resto, un passo alla volta.')+`<form id="search" class="search"><input name="city" aria-label="Città o paese" placeholder="Città o paese" value="${h(query)}"><button aria-label="Cerca">⌕</button><button type="button" data-action="location" aria-label="Usa la mia posizione">◎</button></form><div class="topline"><div class="chips">${[['all','Tutte'],['today','Oggi'],['week','Settimana']].map(([v,l])=>`<button data-day="${v}" class="${day===v?'active':''}">${l}</button>`).join('')}</div><button data-action="filters" aria-label="Filtri">⚑</button></div><div class="sectionhead"><p class="muted">Più imminenti · poi vicinanza, se disponibile</p><button class="link" data-action="map">Mappa ↗</button></div><div class="cards">${events.map((e,i)=>({e,i})).filter(({e})=>!query||e.city.toLowerCase().includes(query.toLowerCase())).filter(()=>day!=='today').map(({i})=>card(i)).join('')||'<p class="card">Nessuna serata per questa ricerca.</p>'}</div>`;
if(page==='detail'){content=back()+head(e.name,`${date(selected)} · ${e.hour}–${e.hour==='20:30'?'22:30':'23:00'}`)+`<div class="topline"><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(e.city)}">${e.venue} · ${e.city} ↗</a><span class="badge">Palestra demo</span></div><div class="twocol"><section><div class="sectionhead"><h2>Chi trovi in campo</h2><span class="badge">${b==='confirmed'||b==='paid'?12:11}/12</span></div><div class="court">${[1,6,5,2,3,4,4,3,2,5,6,1].map((pos,i)=>i===11&&b!=='confirmed'&&b!=='paid'?`<div class="player"><button class="free ${slot===11?'selected':''}" data-action="seat" aria-label="${choosing?'Seleziona posizione 1 squadra B':'Visualizza posto libero'}">${choosing?'＋':'1'}</button><b>Posto libero</b></div>`:`<div class="player"><em>${pos}</em><img src="${photo(i===11?0:i)}" alt="${i===11?'Tu':names[i]} · profilo demo"><b>${i===11?'Tu':names[i]}</b></div>`).join('')}</div><p class="muted">Numeri regolamentari · blu e corallo: due squadre</p><button class="secondary wide" data-action="reserve">Riserve · 2 partecipanti ↗</button></section><aside><div class="card"><span class="eyebrow">La tua serata</span><h2>€${e.price} a persona</h2><p>Ritrovo ${e.hour==='20:30'?'20:00':'20:30'}</p><p class="muted">30 minuti di riscaldamento prima del gioco.</p><hr><p>Amatoriale misto</p><p class="muted">Organizzatrice: Anna · personaggio demo</p><button class="link" data-action="group">Conosci il gruppo →</button></div><div class="stickyaction">${b==='paid'?'<p class="note">✓ Prenotato e pagamento simulato completato</p>':b==='confirmed'?`<button class="primary wide" data-action="pay">Paga ora · €${e.price}</button>`:`<button class="primary wide" data-action="participate">${choosing?'Conferma il posto':'Partecipa alla serata'}</button>`}${b==='confirmed'||b==='paid'?'<button class="link" data-action="cancel">Annulla prenotazione demo</button>':''}</div></aside></div>`;}
if(page==='group'){let joined=state['member'+selected];content=back()+head(e.name,'Un gruppo, prima di una partita.')+`<div class="card">${logo(selected)}<h2>La nostra storia</h2><p>Gruppo dimostrativo di pallavolo amatoriale: ci incontriamo per giocare insieme e conoscere nuove persone.</p><p class="muted">Organizzatrice: Anna · ${e.city} · ${e.members} membri</p><p>Rispetto, puntualità e 30 minuti di riscaldamento insieme.</p><p class="muted">${e.venue} · ${e.hour}</p></div><div class="card"><h2>Entra nel gruppo</h2><div class="steps"><span class="${!joined?'current':''}">1 · Richiedi ingresso</span><span class="${joined==='pending'?'current':''}">2 · Approvazione</span><span class="${joined==='active'?'current':''}">3 · Prenota</span></div>${joined==='active'?'<p>✓ Sei membro. Ora puoi scegliere il tuo posto.</p><button class="primary" data-go="detail">Apri la serata →</button>':joined==='pending'?'<p class="note">Richiesta inviata. Attendi l’organizzatore.</p><button class="link" data-go="manage">Simula il ruolo organizzatore →</button>':'<p class="muted">Prima di prenotare, l’organizzatore deve approvare il tuo ingresso.</p><button class="primary" data-action="join">Richiedi ingresso</button>'}</div><h2>Prossima serata</h2>${card(selected)}`;}
if(page==='home')content=head('Il tuo volley.','Tutto quello che richiede la tua attenzione.')+events.map((e,i)=>status(i)==='confirmed'?`<div class="note"><strong>${e.name}: quota da completare</strong><p>Il posto è confermato. Rimane il pagamento simulato.</p><button class="primary" data-payment="${i}">Paga €${e.price}</button></div>`:'').join('')+`<h2 class="spaced">Le tue prossime partite</h2><div class="cards">${events.map((_,i)=>['confirmed','paid'].includes(status(i))?card(i):'').join('')||'<div class="card"><h2>Il prossimo posto può essere tuo.</h2><p class="muted">Non hai ancora una partita prenotata.</p><button class="primary" data-go="serate">Trova una serata</button></div>'}</div>`;
if(page==='groups')content=head('I tuoi gruppi.','Le persone con cui torni in campo.')+`<button class="secondary" data-go="discover">Scopri altri gruppi ↗</button><div class="cards spaced">${events.map((e,i)=>state['member'+i]==='active'?`<button class="event" data-group="${i}">${logo(i)}<div><h3>${e.name}</h3><small>${e.city} · ${e.members} membri</small></div><span>→</span></button>`:'').join('')||'<div class="card">Non appartieni ancora a un gruppo. Scopri chi gioca vicino a te.</div>'}</div>`;
if(page==='discover')content=back()+head('Trova il tuo gruppo.','Presentazioni e regole prima di entrare.')+`<div class="cards">${events.map((e,i)=>`<button class="event" data-group="${i}">${logo(i)}<div><h3>${e.name}</h3><small>${e.city} · ${e.members} membri</small></div><span>→</span></button>`).join('')}</div>`;
if(page==='manage')content=back()+head('Il tuo spogliatoio.','Pannello organizzatore · simulazione di ruolo locale')+`<div class="dashboard"><div class="metric"><strong>3</strong>Gruppi demo</div><div class="metric"><strong>${events.filter((_,i)=>state['member'+i]==='pending').length}</strong>Richieste in attesa</div><div class="metric"><strong>${events.filter((_,i)=>['confirmed','paid'].includes(status(i))).length}</strong>Prenotazioni della prova</div></div><h2 class="spaced">Richieste di ingresso</h2>${events.map((e,i)=>state['member'+i]==='pending'?`<div class="card"><p>Tu → ${e.name}</p><button class="primary" data-approve="${i}">Accetta</button> <button class="secondary" data-reject="${i}">Rifiuta</button></div>`:'').join('')||'<p class="muted">Nessuna richiesta da gestire.</p>'}<h2 class="spaced">I gruppi che gestisci nella demo</h2>${events.map((e,i)=>`<div class="row">${logo(i)}<div><strong>${e.name}</strong><p class="muted">${e.members} membri · prossima serata ${date(i)}</p></div></div>`).join('')}`;
if(page==='messages')content=back()+head('Messaggi.','Uno spazio per le conversazioni, senza rumore.')+'<div class="card"><h2>Qui iniziano le chiacchiere.</h2><p class="muted">Non hai conversazioni nella nuova proposta. La messaggistica completa rimane nelle tre varianti precedenti.</p></div>';
if(page==='notifications')content=back()+head('Da sapere.','Richieste e pagamenti. I messaggi hanno contatori separati.')+events.map((e,i)=>status(i)==='confirmed'?`<div class="note"><strong>Completa la quota · ${e.name}</strong><p>Il tuo posto è confermato.</p><button class="primary" data-payment="${i}">Paga ora</button></div>`:'').join('')+'<p class="muted spaced">Questi avvisi sono locali e dimostrativi.</p>';
if(page==='profile')content=back()+head('Piacere, sei tu.','Il profilo sintetico, con le informazioni utili per giocare.')+`<div class="card"><img class="profilepic" src="${photo(0)}" alt="Profilo dimostrativo"><h2>Giocatore demo</h2><p>Amatoriale · disponibile la sera</p><p class="muted">Identità e fotografia dimostrative</p><button class="secondary" data-action="profile">Modifica profilo</button></div><div class="card"><h2>Valutazioni</h2><p class="muted">Ancora nessuna valutazione in questa proposta.</p></div>`;
$('#main').innerHTML=content;}
function go(v){page=v;choosing=false;slot=null;render();window.scrollTo(0,0)}
function modal(html){$('#dialogBody').innerHTML=html;$('#modal').showModal()}
document.addEventListener('click',ev=>{let b=ev.target.closest('button');if(!b)return;if(b.dataset.go)return go(b.dataset.go);if(b.dataset.event!==undefined){selected=Number(b.dataset.event);return go('detail')}if(b.dataset.group!==undefined){selected=Number(b.dataset.group);return go('group')}if(b.dataset.day){day=b.dataset.day;return render()}if(b.dataset.approve!==undefined){state['member'+b.dataset.approve]='active';save();return render()}if(b.dataset.reject!==undefined){delete state['member'+b.dataset.reject];save();return render()}if(b.dataset.payment!==undefined){selected=Number(b.dataset.payment);return payment()}let a=b.dataset.action;if(a==='group')go('group');if(a==='join'){state['member'+selected]='pending';save();render()}if(a==='participate'){if(state['member'+selected]!=='active'){go('group');return}if(!choosing){choosing=true;render();$('.court').scrollIntoView({block:'center',behavior:'smooth'});return}if(slot===null){modal('<h2>Scegli un posto nel campo tra quelli a disposizione</h2>');return}state['booking'+selected]='confirmed';save();choosing=false;render();modal('<h2>Il posto è tuo.</h2><p>Prenotazione demo confermata. Puoi completare la quota ora o dalla Home.</p><button class="primary" data-action="pay">Paga ora</button>')}
if(a==='seat'){if(!choosing)return modal('<h2>Posizione 1 · squadra B</h2><p>Premi “Partecipa alla serata” per iniziare la prenotazione.</p>');slot=11;render();$('.stickyaction .primary').focus()}
if(a==='pay')payment();if(a==='finishpay'){state['booking'+selected]='paid';save();$('#modal').close();render()}
if(a==='cancel'){state['booking'+selected]='none';save();render()}if(a==='reserve')modal('<h2>Riserve</h2><p>Due giocatori demo già confermati. In questo scenario i posti riserva sono completi.</p>');if(a==='map')modal('<h2>Scegli una località</h2><p class="muted">Le palestre sono dimostrative: i link cercano la città, senza inventare indirizzi o distanze.</p>'+[...new Set(events.filter(e=>!query||e.city.toLowerCase().includes(query.toLowerCase())).map(e=>e.city))].map(c=>`<p><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(c)}" target="_blank" rel="noopener">${c} ↗</a></p>`).join(''));
if(a==='filters')modal('<h2>Prima le serate imminenti</h2><p>Questa proposta esplora un elenco essenziale. Filtri per livello e raggio saranno da integrare con la ricerca geografica.</p>');if(a==='location'){if(!navigator.geolocation)return modal('<h2>Posizione non disponibile</h2>');navigator.geolocation.getCurrentPosition(()=>modal('<h2>Posizione acquisita</h2><p>Per non mostrare distanze inventate, il calcolo geografico non è simulato. Puoi cercare Brescia o Bergamo.</p>'),()=>modal('<h2>Posizione non disponibile</h2><p>Puoi inserire una città manualmente.</p>'))}if(a==='profile')modal('<h2>Profilo essenziale</h2><p>La modifica completa del profilo resta disponibile nelle varianti precedenti. Questa prova serve a scegliere la nuova struttura.</p>')});
function payment(){if(status(selected)!=='confirmed')return;$('#modal').close();modal(`<h2>Completa la tua serata.</h2><p>${events[selected].name}</p><h1>€${events[selected].price}</h1><p class="muted">Quota demo. Nessuna transazione reale o commissione simulata in questa prova grafica.</p><button class="primary wide" data-action="finishpay">Simula PayPal</button><button class="secondary wide" data-action="finishpay">Simula Satispay</button>`)}
$('#closeDialog').onclick=()=>$('#modal').close();document.addEventListener('submit',e=>{if(e.target.id==='search'){e.preventDefault();query=new FormData(e.target).get('city').trim();render()}});render();
